// Role is NEVER taken from message text. body.role / body.tenant_id are ignored.
// Tenant comes ONLY from the channels lookup (previous node).
// Message fields come ONLY from the Webhook node: in n8n each node's input is
// just the previous node's output, so the message does NOT survive Identify.
// Zero-row lookup output ({"success": true}, no tenant_id) = no channel.
const webhook = $('Webhook').first().json;
const body = webhook.body || webhook;
const row = $input.first().json;
const tenantId = row.tenant_id || null;
let gate = 'proceed';
let role = 'customer';
// ROLE TBD: tenant_members exists (002) but member lookup is not wired yet;
// default stays 'customer' until the Identify query returns member_role.
if (!tenantId) {
  gate = 'blocked_no_channel';
} else if (row.status === 'paused' || row.status === 'cancelled') {
  gate = 'blocked_paused';
}
return [{ json: {
  provider: body.provider,
  external_id: body.external_id,
  channel: body.channel || body.provider,
  channel_user_id: body.channel_user_id,
  message_id: body.message_id || null,
  raw_message: body.payload?.text || body.message || '',
  tenant_id: tenantId,
  sector_code: row.sector_code || null,
  business_name: row.business_name || null,
  tenant_status: row.status || null,
  role: role,
  gate: gate,
  verdict: gate === 'proceed' ? null : gate
} }];

function normalizeArabic(t) {
  if (!t) return '';
  return String(t)
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/ئ/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ـ+/g, '')
    .replace(/[ً-ْ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// SINGLE copy of normalizeArabic in the whole workflow. No other node
// re-implements it; later nodes use normalized_message from this node.
// Map is 7 letters in the SQL translate form: from 'أإآةىئؤ' to
// 'اااهييو';
// standalone hamza ء is left as-is. Keywords below are built from the
// normalized text, never from the raw text.
const src = $input.first().json;
const normalized = normalizeArabic(src.raw_message || '');
const stop = new Set(['انا', 'عايز', 'عايزة', 'اريد', 'كم', 'سعر', 'في', 'من', 'ايه', 'ما', 'هل', 'لو', 'عندكم', 'عندك', 'ابغى', 'ابي', 'ممكن']);
const words = normalized.split(' ').filter(function (w) { return w.length >= 2 && !stop.has(w); });

// Search keywords only (stored names are untouched): strip punctuation, then
// strip the definite-article prefix 'ال' (query side only). Do NOT strip
// ب/و/ف/ل prefixes: e.g. 'وليمة' is a real word, not a prefix.
const pluralToSingular = {'اراضي': 'ارض', 'قطع': 'قطعة'};
const keywords = words.slice(0, 5).map(function (w) {
  var k = w.replace(/[^\p{L}\p{N}\s-]/gu, '');
  if (k.startsWith('ال') && k.length > 2) { k = k.slice(2); }
  if (pluralToSingular[k]) { k = pluralToSingular[k]; }
  return k;
}).filter(function (w) { return w.length >= 1; });
function escapeRegex(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

// intent_key: GENERIC (2026-10-31, approved design). The normalized
// question text itself is the key — any repeated question, any sector.
// Normalization collapses variants onto one form (قائمة/قائمه -> قايمه,
// خدمة -> خدمه), so the same question asked in any variant hits one key.
// intent_key: GENERIC — the normalized question itself, ANY sector.
// Same normalized question + same tenant + same data_hash => cache hit.
// Empty normalized text => null (no key, no cache write/lookup).
// Tenant isolation comes from tenant_id in the cache key, not from here.
const intent_key = normalized ? normalized : null;

return [{ json: Object.assign({}, src, {
  normalized_message: normalized,
  keywords: keywords,
  search_regex: keywords.map(escapeRegex).join('|'),
  intent_key: intent_key
}) }];

// BRAIN REPLACEMENT 2026-10-30: sector voice comes ONLY from the sector pack in Load Tenant Data (pack inserted as-is). No inline sector lookup remains in this node.
// MERGE 2026-10-30: projectIndex carries name + area + city + attributes; one hard anti-inference rule added to the base honesty rules.
// STAGE 2 2026-10-30: owner voice block inserted after the pack section and before the memory section; voice comes ONLY from tenant_voice_settings via Load Tenant Data (voice inserted as-is, no dialect branches).
const s = $('Load Tenant Data').first().json;
const system = "You serve this tenant only. The following rows are this tenant's own complete data for this question — nothing hidden, nothing truncated. Answer from them completely, in detail, in this sector's selling way.\nYou are the Barqlo sales brain. Reply in clear Arabic. Never invent a price, count, date, or attribute. Use ONLY the attached tenant data. If information is missing from the attached data, say so honestly and do not complete it by guessing. Never mention another tenant, tenant ids, or internal identifiers. Output JSON ONLY with fields reply_text, cited_items (item id + field + value), confidence (high/low). If you cannot cite from attached data, set confidence to low and declare the gap. A short message naming one item IS a question about that item – answer it directly, and never claim the message did not arrive when its text is present in the request. When relevant_items, projects, or project_index rows are attached in the prompt, never state that their details are missing, unattached, or unavailable; a detail may be declared missing only for a specific field that is genuinely absent from the attached rows themselves, for example total price may be declared missing when only price-per-sqm is present. Land-price rule: for land rows where price is null, use price_per_sqm; show سعر المتر + area_sqm; never present a per-sqm figure as a total price; never compute an unlabeled total from per-sqm and area. Rent rule: for rows with listing=rent, label the price إيجار شهري and never present it as a sale price. Filtered-list exclusion rule: when a list is delivered filtered by an attribute (for example a doctor name), name the excluded class explicitly in the reply (for example, the services of أي طبيب آخر are excluded). Status rule (general, data-driven, not sector logic): EVERY row that has a status field MUST show its status in its line, in Arabic (available → متاح, booked → محجوز, sold → مباع); lands lines = name + per-sqm price + area + status; units lines = their existing attributes + status; rows without a status field (menu items, services) are unaffected. Never present a clinic-wide working-days value as a specific doctor's attendance days; never derive a floor from a unit code.";
const projectIndex = (s.project_index || []).map(function(p) { return {name: p.name, area: p.area, city: p.city, attributes: p.attributes};});
const totalProjects = s.totals && s.totals.projects_count!== undefined? s.totals.projects_count: projectIndex.length;
const normNode = $('Normalize Arabic').first().json;
const currentMessage = normNode.normalized_message || '';
const currentRaw = normNode.raw_message || '';
// Prompt trimming: remove the current message from history (it already appears under CURRENT MESSAGE below), keep the last 8 otherwise. Policies are left as they are.
const seenHistory = new Set();
const cleanHistory = (s.history || []).filter(function(h) { const content = (h && h.content) || ''; if (content && (content === currentMessage || content === currentRaw)) return false; const key = String(content) + '||' + String((h && h.sender_role) || ''); if (seenHistory.has(key)) return false; seenHistory.add(key); return true;}).slice(0, 8);
const collectionSet = s.collection_set || [];
const collectionMeta = s.collection_meta || null;
const collectionSection = collectionMeta? '\nCollection set (attached in order, tier: ' + collectionMeta.tier + ', total_count: ' + collectionMeta.total_count + ', attached_count: ' + collectionMeta.attached_count + ', collection_key: ' + collectionMeta.collection_key + ', scope category: ' + (collectionMeta.category || '') + ', scope kind: ' + (collectionMeta.kind || '') + ', categories: ' + JSON.stringify(collectionMeta.categories || []) + ', kind_legend: ' + JSON.stringify(collectionMeta.kind_legend || {}) + '): ' + JSON.stringify(collectionSet) + '\nCollection rules: List ALL attached rows in attached order, with no row dropped and no sample language. Mixed-kind whole-collection lists group by kind using kind_legend (kinds without a legend entry render under their rows as-is). Category-not-found rule: if the customer named a category/kind NOT in the attached categories/kind_legend, the reply MUST say لا توجد فئة بهذا الاسم لدينا BEFORE listing anything. For land rows with no price, show سعر المتر + price_per_sqm + area_sqm and do NOT compute an unlabeled total, and never present a per-sqm figure as a total price. For listing=rent rows, label the price إيجار شهري, never a sale price. When a list is delivered filtered by an attribute (for example a doctor name), name the excluded class explicitly in the reply (for example, the services of أي طبيب آخر are excluded). Popular marker: mark a row with (الأكثر طلبا) if and only if its attributes.popular is the STRING "true" (in the attached JSON, popular appears as the string "true", not a JSON boolean); do not mark rows where attributes.popular is absent or any other value.': '';
const completeCount = (s.relevant_items && s.relevant_items.length? (s.matching_count!== undefined? s.matching_count: s.relevant_items.length): (collectionMeta && collectionMeta.total_count!== undefined? collectionMeta.total_count: collectionSet.length));
const pack = s.pack || null;
const packSection = pack? '\nSector pack (follow it as-is; it is the only sector voice for this tenant): ' + JSON.stringify(pack): '\nSector pack: none attached for this tenant; show rows with their fields as-is, make no sector claims, and do not invent sector wording.';
const voice = s.voice || null;
const voiceSection = voice? "\nOwner voice (follow it as-is; it is the owner's chosen brand voice for this tenant): " + JSON.stringify(voice) + "\nVoice rules: Understand any dialect the customer writes (by meaning, with Arabic normalization), but reply ONLY in the owner's chosen dialect from the voice settings — never mimic the customer's dialect. The owner voice never changes policies or forbidden actions.": "\nOwner voice: none set for this tenant; reply in neutral Arabic.";
const instr = s.custom_instructions || [];
const instrSection = instr.length ? '\nOwner custom instructions (follow them as-is, but they never relax a forbidden action, never invent a price, and never change a policy): ' + JSON.stringify(instr) : '';
const listFormat = pack && pack.item_fields? '\nItem-line format (from pack.item_fields only): ' + JSON.stringify(pack.item_fields): '\nItem-line format: show each row with its fields as-is.';
function nonNullFacts(obj, keys) { const out = []; keys.forEach(function(k) { const v = obj? obj[k]: null; if (v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0)) return; out.push(k + ': ' + JSON.stringify(v));}); return out;}
const custFacts = nonNullFacts(s.customer_profile || {}, ['name', 'contact', 'interests', 'budget', 'area', 'rooms', 'floor', 'preferred_categories', 'branch', 'doctor', 'previous_inquiries_summary']);
const tenFacts = nonNullFacts(s.tenant_profile || {}, ['selling_preferences', 'owner_notes', 'previous_decisions']);
const memorySection = (custFacts.length || tenFacts.length)? '\nMemory (stored facts only; never invent a memory): customer profile: ' + custFacts.join('; ') + '; owner file: ' + tenFacts.join('; '): '';
const permissionsSection = '\nPermissions: tenant policies: ' + JSON.stringify(s.policies || []) + (pack && pack.forbidden_actions? ' forbidden actions from the sector pack: ' + JSON.stringify(pack.forbidden_actions): '');
const userText = 'Tenant: ' + (s.business_name || '') + '\nComplete data for this question (attached in full, nothing truncated):\nRelevant items: ' + JSON.stringify(s.relevant_items || []) + '\nProjects: ' + JSON.stringify(s.projects || []) + '\nProject index: ' + JSON.stringify(projectIndex) + '\nTotal projects: ' + totalProjects + '\nProject instruction: use the project index to attach each item to its project, including the project area, city and attributes (type, delivery, amenities, description) where present; never invent project details.\nArea index: ' + JSON.stringify(s.area_items || []) + '\nArea instruction: use the area index only for area values present in the attached rows.\nTotals: ' + JSON.stringify(s.totals || {}) + '\nComplete count: ' + completeCount + collectionSection + '\nPolicies: ' + JSON.stringify(s.policies || []) + listFormat + packSection + voiceSection + instrSection + memorySection + permissionsSection + '\nHistory (most recent first, excluding the current message): ' + JSON.stringify(cleanHistory) + '\nCURRENT MESSAGE: ' + currentMessage + (currentRaw && currentRaw!== currentMessage? ' (raw: ' + currentRaw + ')': '') + '\nAnswer the current question alone, from the attached data for this question only.';
return [{json: Object.assign({}, s, {prompt_messages: [{role: 'system', content: system}, {role: 'user', content: userText}]})}];

const prep = $input.first().json;
const load = $('Load Tenant Data').first().json;
const norm = $('Normalize Arabic').first().json;
const rawContent = (prep.choices && prep.choices[0] && prep.choices[0].message && prep.choices[0].message.content) || prep.reply_text || '';
let draft = null;
try { draft = JSON.parse(rawContent); } catch (e) { draft = { reply_text: rawContent, cited_items: [], confidence: 'low' }; }
const reply = draft.reply_text || '';
const cited = draft.cited_items || [];
const confidence = draft.confidence || 'low';
const attached = JSON.stringify(load.relevant_items || []) + ' ' + JSON.stringify(load.collection_set || []) + ' ' + JSON.stringify(load.projects || []) + ' ' + JSON.stringify(load.project_index || []) + ' ' + JSON.stringify(load.policies || []);
const totals = load.totals || {};
const checks = [];
function check(rule, passed, reason) { checks.push({ rule: rule, passed: passed, reason: reason }); }
function normText(x) { return String(x || '').replace(/[\u0640\u064B-\u0652\u0670]/g, '').replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/ئ/g, 'ي').replace(/ؤ/g, 'و').replace(/[\u06CC]/g, 'ي').replace(/[\u06A9]/g, 'ك'); }
function rowPriceNum(r) { if (!r || r.price === undefined || r.price === null) { return null; } const s = String(r.price).replace(/[^0-9.]/g, ''); return s ? Number(s) : null; }
function rowUnit(r) { if (!r) { return ''; } const a = r.attrs || r.attributes || {}; const u = (a.unit !== undefined && a.unit !== null) ? a.unit : (r.unit || ''); return normText(u); }
function rowPerSqmNum(r) { if (!r) { return null; } const a = r.attrs || r.attributes || {}; let v = (r.price_per_sqm !== undefined && r.price_per_sqm !== null) ? r.price_per_sqm : ((a.price_per_sqm !== undefined && a.price_per_sqm !== null) ? a.price_per_sqm : null); if (v === null || v === undefined) { return null; } const s = String(v).replace(/[^0-9.]/g, ''); return s ? Number(s) : null; }
const collectionMeta0 = load.collection_meta || null;
const collectionSet0 = load.collection_set || [];
const priceRows = [];
for (const r of (load.relevant_items || [])) { const nm = normText(r && r.name); if (nm) { priceRows.push({ name: r.name, normName: nm, priceNum: rowPriceNum(r), perSqmNum: rowPerSqmNum(r), unit: rowUnit(r), kind: r.kind || null, text: normText(JSON.stringify(r || {})) }); } }
for (const r of collectionSet0) { const nm = normText(r && r.name); if (nm) { priceRows.push({ name: r.name, normName: nm, priceNum: rowPriceNum(r), perSqmNum: rowPerSqmNum(r), unit: rowUnit(r), kind: r.kind || null, text: normText(JSON.stringify(r || {})) }); } }
const priceRe = /[\d,]+(?:\.\d+)?\s*(?:ريال|جنيه|SAR|EGP|ج\.م)/g;
const unitPhrases = ['ربع كيلو', 'نصف كيلو', 'كيلو', 'كوب', 'طبق', 'قطعة', 'علبة'];
let r1 = true, r1reason = 'all prices found in attached data';
let pm;
let lastLineStart = -1;
let searchFrom = 0;
while ((pm = priceRe.exec(reply)) !== null) {
  const numTokMatch = pm[0].match(/[\d,]+(?:\.\d+)?/);
  const citedNumToken = numTokMatch ? numTokMatch[0] : '';
  const citedNumStr = citedNumToken.replace(/,/g, '');
  const citedNum = Number(citedNumStr);
  let lineStart = reply.lastIndexOf('\n', pm.index - 1) + 1;
  let lineEnd = reply.indexOf('\n', pm.index);
  if (lineEnd === -1) { lineEnd = reply.length; }
  const rawLine = reply.slice(lineStart, lineEnd);
  const normLine = normText(rawLine);
  if (lineStart !== lastLineStart) { lastLineStart = lineStart; searchFrom = 0; }
  let priceIdxNorm = citedNumToken ? normLine.indexOf(citedNumToken, searchFrom) : -1;
  if (priceIdxNorm === -1 && citedNumStr) { priceIdxNorm = normLine.indexOf(citedNumStr, searchFrom); }
  if (priceIdxNorm === -1 && citedNumToken) { priceIdxNorm = normLine.indexOf(citedNumToken); }
  if (priceIdxNorm !== -1) { searchFrom = priceIdxNorm + citedNumToken.length; }
  let segStart = 0;
  let segEnd = normLine.length;
  if (priceIdxNorm !== -1) {
    for (let i = priceIdxNorm - 1; i >= 0; i--) {
      const ch = normLine[i];
      if (ch === ',' || ch === '،' || ch === ';' || ch === '؛' || ch === '|') {
        if (ch === ',' && i > 0 && i + 1 < normLine.length && /[0-9]/.test(normLine[i - 1]) && /[0-9]/.test(normLine[i + 1])) { continue; }
        segStart = i + 1; break;
      }
    }
    for (let i = priceIdxNorm + 1; i < normLine.length; i++) {
      const ch = normLine[i];
      if (ch === ',' || ch === '،' || ch === ';' || ch === '؛' || ch === '|') {
        if (ch === ',' && i > 0 && i + 1 < normLine.length && /[0-9]/.test(normLine[i - 1]) && /[0-9]/.test(normLine[i + 1])) { continue; }
        segEnd = i; break;
      }
    }
  }
  const segNorm = normLine.slice(segStart, segEnd);
  let lineUnit = '';
  for (const up of unitPhrases) { if (segNorm.indexOf(normText(up)) !== -1) { lineUnit = normText(up); break; } }
  const occs = [];
  for (const pr of priceRows) {
    let from = 0;
    while (from < normLine.length) {
      const ni = normLine.indexOf(pr.normName, from);
      if (ni === -1) { break; }
      occs.push({ row: pr, start: ni, end: ni + pr.normName.length });
      from = ni + 1;
    }
  }
  let chosen = null;
  if (priceIdxNorm !== -1 && occs.length > 0) {
    const inSegPre = occs.filter(function(o) { return o.start >= segStart && o.end <= priceIdxNorm; });
    const onLinePre = occs.filter(function(o) { return o.end <= priceIdxNorm; });
    const pool = inSegPre.length > 0 ? inSegPre : onLinePre;
    if (pool.length > 0) {
      pool.sort(function(a, b) { if (b.end !== a.end) { return b.end - a.end; } return b.row.normName.length - a.row.normName.length; });
      chosen = pool[0].row;
    }
  }
  if (!chosen && occs.length > 0) {
    let best = null; let bestDist = Infinity;
    for (const o of occs) {
      const dist = priceIdxNorm === -1 ? Math.abs(o.start) : Math.abs(o.start - priceIdxNorm);
      if (dist < bestDist || (dist === bestDist && best && o.row.normName.length > best.row.normName.length)) { best = o; bestDist = dist; }
    }
    if (best) { chosen = best.row; }
  }
  if (chosen) {
    const unitOk = (lineUnit === '' || chosen.unit === '' || chosen.unit === lineUnit || (chosen.text && chosen.text.indexOf(lineUnit) !== -1));
    const perSqmOk = (chosen.priceNum === null && chosen.perSqmNum !== null && chosen.perSqmNum === citedNum && (normLine.indexOf('متر') !== -1 || rawLine.indexOf('م²') !== -1));
    if (perSqmOk) { continue; }
    if (chosen.priceNum !== null && chosen.priceNum === citedNum && unitOk) { continue; }
    r1 = false;
    if (!unitOk) { r1reason = 'price_real: reply says ' + pm[0] + ' for ' + chosen.name + ', attached price is ' + chosen.priceNum + ', attached unit is ' + chosen.unit + ' (reply unit ' + lineUnit + ')'; }
    else { r1reason = 'price_real: reply says ' + pm[0] + ' for ' + chosen.name + ', attached price is ' + chosen.priceNum; }
    break;
  }
  const anyRowHas = priceRows.some(function(pr) { return pr.priceNum !== null && pr.priceNum === citedNum; });
  const perSqmRowHas = priceRows.some(function(pr) { return pr.priceNum === null && pr.perSqmNum !== null && pr.perSqmNum === citedNum; });
  const perSqmLineOk = (normLine.indexOf('متر') !== -1 || rawLine.indexOf('م²') !== -1);
  if (perSqmRowHas && perSqmLineOk) { continue; }
  if (!anyRowHas && attached.indexOf(citedNumStr) === -1) { r1 = false; r1reason = 'price not in attached tenant data: ' + pm[0]; break; }
}
check('price_real', r1, r1reason);
let r2 = true, r2reason = 'all cited items found in attached data';
for (const c of cited) {
  const name = (c && (c.name || c.item_name || c.id || c.item_id)) || '';
  if (name && attached.indexOf(String(name)) === -1) { r2 = false; r2reason = 'cited item not in attached data: ' + name; break; }
}
check('item_real', r2, r2reason);
const replyForDenial = reply.split('\n').filter(function (l) { return !/ملاحظة شفافية/.test(l); }).join('\n');
const denial = /(لا يوجد|غير متوفر|لا توجد|غير متاح|لا أجد|لا اجد|لم أجد|غير موجود|لا يوجد لدينا|not available|no units|not found)/.test(replyForDenial);
let r3 = true;
const emptySearch = (load.search_ran === true && Number(load.matching_count || 0) === 0 && !load.truncated);
if (denial && !emptySearch) { r3 = false; }
check('denial_with_search', r3, r3 ? 'denial backed by empty search' : (load.truncated ? 'denial despite truncated search: attached top rows may omit the named item' : 'denial without a real empty search'));
const normReplyForAll = normText(reply);
const replyForAll = normReplyForAll.replace(/كل تفاصيل(ها|ه|هم|هن| المشروع| الوحده| المنتج| الخدمه)?/g, '');
const hasPartialNotice = /(عرض جزئي|من أصل|من اصل)/.test(reply) || /(عرض جزيي|من اصل)/.test(normReplyForAll) || /\d+\s+من\s+أصل/.test(reply);
const allClaim = !hasPartialNotice && ((/(^|[^\p{L}\p{N}_])(الكل|جميع|كل)(ها|هم|هن|ه)?(?![\p{L}\p{N}_])/u.test(replyForAll)) || /(^|[^\p{L}\p{N}_])all(?![\p{L}\p{N}_])/iu.test(replyForAll));
let r4 = true, r4reason = 'all-claim matches tenant total or absent';
if (allClaim) {
  const normReplyAll = normText(reply);
  const allNames = new Set();
  for (const r of (load.relevant_items || [])) { const nm = normText(r && r.name); if (nm) { allNames.add(nm); } }
  for (const r of collectionSet0) { const nm = normText(r && r.name); if (nm) { allNames.add(nm); } }
  for (const p of (load.projects || [])) { const nm = normText(p && p.name); if (nm) { allNames.add(nm); } }
  for (const p of (load.project_index || [])) { const nm = normText(p && p.name); if (nm) { allNames.add(nm); } }
  let distinctCited = 0;
  allNames.forEach(function(nm) { if (normReplyAll.indexOf(nm) !== -1) { distinctCited++; } });
  const isProjectClaim = /(مشاريع|مشروع)/.test(reply);
  const isServiceClaim = /(خدمات|خدمة)/.test(reply);
  let totalAll;
  if (collectionMeta0) { totalAll = Number(collectionMeta0.total_count || 0); }
  else { totalAll = isProjectClaim ? Number(totals.projects_count || 0) : isServiceClaim ? Number(totals.services_count || 0) : Number(totals.items_count || 0); }
  if (totalAll > 0 && distinctCited !== totalAll) { r4 = false; r4reason = 'all-claim from a sample: cited ' + distinctCited + ' of ' + totalAll + ' (attached total is ' + totalAll + ')'; }
}
check('no_all_from_sample', r4, r4reason);
const replyForCount = reply.replace(/[A-Za-z]+\d+-[A-Za-z]+\d+/g, ' ');
const countRe = /(\d+)\s*(وحدات|وحدة|مشاريع|مشروع|خدمات|خدمة|أراضي|اراضي|أرض|ارض|قطعة|قطعه|قطع)/g;
const pluralToSingular = {'وحدات': 'وحدة', 'مشاريع': 'مشروع', 'خدمات': 'خدمة', 'أراضي': 'أرض', 'اراضي': 'أرض', 'أرض': 'أرض', 'ارض': 'أرض', 'قطعة': 'قطعة', 'قطعه': 'قطعة', 'قطع': 'قطعة'};
let countMap = load.count_map || {};
if (typeof countMap === 'string') { try { countMap = JSON.parse(countMap); } catch (e) { countMap = {}; } }
const attachedKinds = new Set();
